#!/usr/bin/env python3
"""Install resilient map-v3 enhancements: intensity toggle and regional coverage stats."""
from pathlib import Path
INDEX=Path(__file__).resolve().parent/'index.html'
MARK='<!-- GP-MAP-V3-ENHANCEMENTS -->'
CSS='''<style id="gp-map-v3-css">.gp-map-v3{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin:-2px 0 9px}.gp-map-v3 button{font-size:10px;min-height:34px;padding:7px 9px}.gp-map-v3 button.active{border-color:var(--amber);color:var(--amber);background:rgba(255,200,87,.1)}.gp-region-stats{display:flex;gap:7px;overflow:auto;margin:0 0 9px;padding-bottom:2px}.gp-region-stat{min-width:110px;padding:8px 9px;border:1px solid var(--line);border-radius:9px;background:#08131e}.gp-region-stat b{display:block;font-size:16px}.gp-region-stat span{font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}.gp-heat-legend{font-size:9px;color:var(--muted);margin:0 0 8px}</style>'''
JS=r'''<script id="gp-map-v3-js">(function(){"use strict";let installed=false,heat=null,heatOn=false;const esc=v=>String(v??"").replace(/[&<>\"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));const regionOf=m=>String(m?.region||m?.country||"Other").trim()||"Other";const valid=m=>Number.isFinite(Number(m?.lat??m?.latitude))&&Number.isFinite(Number(m?.lng??m?.lon??m?.longitude));function boot(){if(installed||!window.L||!window.DATA||!document.querySelector("#map"))return;const bar=document.querySelector(".gp-mapbar");if(!bar)return;installed=true;const row=document.createElement("div");row.className="gp-map-v3";row.innerHTML='<button type="button" id="gpHeatToggle">INTENSITY OFF</button><button type="button" id="gpFitAll">FIT ALL</button><span class="gp-map-count" id="gpRegionTotal"></span>';bar.parentElement.insertBefore(row,bar.nextSibling);const stats=document.createElement("div");stats.className="gp-region-stats";bar.parentElement.insertBefore(stats,row.nextSibling);const legend=document.createElement("div");legend.className="gp-heat-legend";legend.textContent="Intensity = concentration of sourced map signals; not a prediction or casualty measure.";bar.parentElement.insertBefore(legend,stats.nextSibling);function points(){return(Array.isArray(DATA.markers)?DATA.markers:[]).filter(valid).map(m=>[Number(m.lat??m.latitude),Number(m.lng??m.lon??m.longitude),Math.max(.2,Math.min(1.5,Number(m.importance||1))),m])}function drawHeat(){if(!window.gpGlobalMap)return;if(heat){window.gpGlobalMap.removeLayer(heat);heat=null}if(!heatOn)return;const pts=points();if(window.L.heatLayer){heat=L.heatLayer(pts.map(x=>[x[0],x[1],x[2]]),{radius:28,blur:24,maxZoom:7,max:1.5});heat.addTo(window.gpGlobalMap)}else{heat=L.layerGroup();const seen=new Map();pts.forEach(x=>{const k=Math.round(x[0])+","+Math.round(x[1]);seen.set(k,(seen.get(k)||0)+x[2])});seen.forEach((v,k)=>{const[a,b]=k.split(',').map(Number);L.circle([a,b],{radius:Math.min(120000,18000*Math.sqrt(v)),color:'#ffc857',weight:1,fillOpacity:.12}).addTo(heat)});heat.addTo(window.gpGlobalMap)}}function regionStats(){const counts={};points().forEach(x=>{const r=regionOf(x[3]);counts[r]=(counts[r]||0)+1});const top=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,8);stats.innerHTML=top.map(([r,n])=>'<div class="gp-region-stat"><b>'+n+'</b><span>'+esc(r)+'</span></div>').join('');document.getElementById('gpRegionTotal').textContent=Object.values(counts).reduce((a,b)=>a+b,0)+' mapped signals'}document.getElementById('gpHeatToggle').onclick=()=>{heatOn=!heatOn;document.getElementById('gpHeatToggle').textContent=heatOn?'INTENSITY ON':'INTENSITY OFF';document.getElementById('gpHeatToggle').classList.toggle('active',heatOn);drawHeat()};document.getElementById('gpFitAll').onclick=()=>{const p=points();if(p.length&&window.gpGlobalMap)window.gpGlobalMap.fitBounds(L.latLngBounds(p.map(x=>[x[0],x[1]])).pad(.06),{maxZoom:5})};regionStats();const old=window.renderMap;if(typeof old==='function')window.renderMap=function(){old();setTimeout(()=>{regionStats();drawHeat()},20)};setTimeout(drawHeat,50)}const t=setInterval(()=>{if(installed||boot())clearInterval(t)},250);setTimeout(()=>clearInterval(t),30000)})();</script>'''
s=INDEX.read_text(encoding='utf-8');start=s.find(MARK)
if start>=0:
 end=s.find('</body>',start);s=s[:start]+MARK+'\n'+CSS+'\n'+JS+'\n'+s[end:]
else:
 s=s.replace('</head>',CSS+'\n</head>',1);s=s.replace('</body>',MARK+'\n'+JS+'\n</body>',1)
INDEX.write_text(s,encoding='utf-8');print('Installed map v3 enhancements')
